mapper.sql:
WHERE landed_costs.status >= 0

    AND landed_costs.date >= #{filter.date}


    AND landed_costs.status = #{filter.status}


    AND landed_costs.vendor_id = #{filter.vendorId}


    AND landed_costs.created_by = #{userId}


    AND (
    landed_cost_types.name LIKE CONCAT("%", #{filter.searchText}, "%")
    OR landed_costs.code LIKE CONCAT("%", #{filter.searchText}, "%")
    OR paidTo.name LIKE CONCAT("%", #{filter.searchText}, "%")
    )

mapper.select:
SELECT



ORDER BY


        ${filter.orderBy}


        landed_costs.id DESC



    LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT COUNT(id)
FROM landed_costs
WHERE is_active = 1 AND name = #{name}
 AND id != #{id}

